#!/usr/bin/env bash
set -euo pipefail

BASE="$HOME/PokemonRedExperiments-v2/v2"
PYENV="$HOME/miniconda3/envs/pokemonredv2/bin/python"
BACKUP_ROOT="$HOME/pokemonred_backups"
cd "$BASE"

echo "============================================================"
echo " Pokemon Red AI V3.2 - AUTO SPEED BALANCER"
echo "============================================================"
echo
echo "Agent 1 wordt automatisch ongeveer even snel gehouden als"
echo "één PPO-trainingagent, ongeacht 11, 19 of een ander aantal trainers."
echo

check_allowed() {
    local file="$1"
    shift
    local actual
    actual="$(sha256sum "$file" | awk '{print $1}')"
    for expected in "$@"; do
        if [[ "$actual" == "$expected" ]]; then
            echo "OK: $file"
            return 0
        fi
    done
    echo "FOUT: onbekende versie van $file"
    echo "Actueel: $actual"
    echo "Er wordt niets gewijzigd."
    exit 1
}

echo "== 1. Broncode controleren =="
check_allowed baseline_fast_v2.py 548a60ae2a2e95a09fb8a92dabb5be94c7634ce02385f505c1e6043cd98b340f e7821c8f994e9d662390877cf8f6cfd8740d7e19f2099192ff3a1784261e4587
check_allowed persistent_explorer_callback.py 9d427fd7296b37595c616aef71687555443b7fe9eb16220e8ebef20483cc7197 a9c558ee0b02a9113b21b88995e45dd12044746a57477fb21e34609e7f1c173a
check_allowed live_server.py 52364fcdb80e890ef03ce1fb45689468c18ab10aad497a28341ddd45af018fde 8394b46d8c4966e9221329e3ad1499fce3ba56d845d3dcdd2cd030dad6e68bb7
check_allowed red_gym_env_v2.py eb09c801b38733861187c103634483893961627e2cdd1fb6cd973e3dafc947ba
check_allowed tensorboard_callback.py 8d9845ecb20144ba49d83a5dfa899de61f40a6d9fd73249a1bbd417aaea0c526

echo
echo "== 2. Bot netjes stoppen =="
if [[ -x ./stop_pokemonred_v3_1.sh ]]; then
    ./stop_pokemonred_v3_1.sh || true
else
    tmux send-keys -t pokemonred C-c 2>/dev/null || true
    sleep 10
    pkill -f '[b]aseline_fast_v2.py' 2>/dev/null || true
    tmux kill-session -t pokemonred 2>/dev/null || true
    tmux kill-session -t pokemonlive 2>/dev/null || true
    tmux kill-session -t tensorboard 2>/dev/null || true
    pkill -f '[l]ive_server.py' 2>/dev/null || true
    pkill -f '[t]ensorboard' 2>/dev/null || true
fi

if pgrep -f '[b]aseline_fast_v2.py' >/dev/null 2>&1; then
    echo "FOUT: PPO draait nog."
    exit 1
fi

echo
echo "== 3. Volledige backup =="
mkdir -p "$BACKUP_ROOT"
STAMP="$(date +%Y%m%d_%H%M%S)"
BACKUP="$BACKUP_ROOT/PokemonRedExperiments-v2_before_V3_2_${STAMP}.tar.gz"
tar -czf "$BACKUP" -C "$HOME" PokemonRedExperiments-v2
sha256sum "$BACKUP" > "$BACKUP.sha256"
sha256sum -c "$BACKUP.sha256"

echo
echo "== 4. Nieuwe V3.2-code offline bouwen =="
TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT
cat > "$TMP/baseline_fast_v2.py.b64" <<'EOF_baseline_fast_v2_py'

EOF_baseline_fast_v2_py
base64 -d "$TMP/baseline_fast_v2.py.b64" > "$TMP/baseline_fast_v2.py"

cat > "$TMP/persistent_explorer_callback.py.b64" <<'EOF_persistent_explorer_callback_py'

EOF_persistent_explorer_callback_py
base64 -d "$TMP/persistent_explorer_callback.py.b64" > "$TMP/persistent_explorer_callback.py"

cat > "$TMP/live_server.py.b64" <<'EOF_live_server_py'

EOF_live_server_py
base64 -d "$TMP/live_server.py.b64" > "$TMP/live_server.py"


"$PYENV" -m py_compile   "$TMP/baseline_fast_v2.py"   "$TMP/persistent_explorer_callback.py"   "$TMP/live_server.py"

"$PYENV" - "$TMP" <<'PY'
from pathlib import Path
import ast, sys

root = Path(sys.argv[1])
baseline = (root / "baseline_fast_v2.py").read_text()
callback = (root / "persistent_explorer_callback.py").read_text()
viewer = (root / "live_server.py").read_text()

assert 'POKEMON_TOTAL_AGENTS' in baseline
assert 'total_agents - 1' in baseline
assert 'AGENT1_SPEED_RATIO' in baseline
assert 'num_train_envs=num_train_envs' in baseline

assert '_agent1_balance_snapshot' in callback
assert 'ppo_timesteps_value' in callback
assert 'ppo_delta / float(train_envs)' in callback
assert 'balance["ahead_steps"] > 0' in callback
assert 'time.sleep(sleep_seconds)' in callback
assert 'rollout_buffer.add' not in callback

tree = ast.parse(callback)
cls = next(n for n in tree.body if isinstance(n, ast.ClassDef) and n.name == "PersistentExplorerCallback")
on_step = next(n for n in cls.body if isinstance(n, ast.FunctionDef) and n.name == "_on_step")
calls = []
for node in ast.walk(on_step):
    if isinstance(node, ast.Call):
        fn = node.func
        if isinstance(fn, ast.Attribute):
            calls.append(fn.attr)
assert "step" not in calls
assert "predict" not in calls

assert "READ-ONLY AUTO" in viewer
assert "explorer_train_envs" in viewer
assert "explorer_ahead_steps" in viewer

print("V3.2 checks: OK")
print(" - dynamic total-agent count")
print(" - Agent 1 target = per-trainer PPO progress")
print(" - automatic throttle when Agent 1 is ahead")
print(" - full-speed catch-up when Agent 1 is behind")
print(" - no Agent-1 rollout-buffer writes")
print(" - parent PPO callback performs no env.step/predict")
PY

echo
echo "== 5. Installeren =="
CODE_BACKUP="$BASE/v32_backups/$STAMP"
mkdir -p "$CODE_BACKUP"
cp -a baseline_fast_v2.py persistent_explorer_callback.py live_server.py "$CODE_BACKUP/"

install -m 664 "$TMP/baseline_fast_v2.py" "$BASE/baseline_fast_v2.py"
install -m 664 "$TMP/persistent_explorer_callback.py" "$BASE/persistent_explorer_callback.py"
install -m 664 "$TMP/live_server.py" "$BASE/live_server.py"

cat > "$BASE/start_pokemonred_v3_2.sh" <<'STARTV32'
#!/usr/bin/env bash
set -euo pipefail

BASE="$HOME/PokemonRedExperiments-v2/v2"
cd "$BASE"

# Usage:
#   ./start_pokemonred_v3_2.sh       -> 12 total agents
#   ./start_pokemonred_v3_2.sh 20    -> 20 total agents (1 explorer + 19 PPO)
#   ./start_pokemonred_v3_2.sh auto  -> 20 on >=28 GiB RAM, otherwise 12
REQUESTED="${1:-${POKEMON_TOTAL_AGENTS:-12}}"

MEM_KIB="$(awk '/MemTotal:/ {print $2}' /proc/meminfo)"
MEM_GIB=$(( MEM_KIB / 1024 / 1024 ))

if [[ "$REQUESTED" == "auto" ]]; then
    if (( MEM_GIB >= 28 )); then
        TOTAL_AGENTS=20
    else
        TOTAL_AGENTS=12
    fi
else
    TOTAL_AGENTS="$REQUESTED"
fi

if ! [[ "$TOTAL_AGENTS" =~ ^[0-9]+$ ]] || (( TOTAL_AGENTS < 2 )); then
    echo "FOUT: totaal aantal agents moet een getal >= 2 zijn."
    exit 1
fi

if (( TOTAL_AGENTS >= 20 && MEM_GIB < 28 )) && [[ "${POKEMON_FORCE_AGENTS:-0}" != "1" ]]; then
    echo "FOUT: $TOTAL_AGENTS agents gevraagd met slechts ~${MEM_GIB} GiB RAM."
    echo "Voor 20 agents vereist deze helper minimaal ~28 GiB gedetecteerd RAM."
    echo "Override alleen bewust met: POKEMON_FORCE_AGENTS=1"
    exit 1
fi

TARGET_RATIO="${AGENT1_SPEED_RATIO:-1.0}"
LEAD_STEPS="${AGENT1_LEAD_STEPS:-128}"

echo "Pokemon Red AI V3.2"
echo "RAM gedetecteerd : ~${MEM_GIB} GiB"
echo "Totaal agents    : ${TOTAL_AGENTS}"
echo "PPO trainers     : $((TOTAL_AGENTS - 1))"
echo "Agent 1 target   : ${TARGET_RATIO}x snelheid van 1 PPO trainer"
echo "Lead buffer      : ${LEAD_STEPS} steps"

tmux kill-session -t pokemonred 2>/dev/null || true
tmux kill-session -t pokemonlive 2>/dev/null || true
tmux kill-session -t tensorboard 2>/dev/null || true
pkill -f '[b]aseline_fast_v2.py' 2>/dev/null || true
pkill -f '[l]ive_server.py' 2>/dev/null || true
pkill -f '[t]ensorboard' 2>/dev/null || true

rm -f runs/curframe_*.jpeg runs/curframe_*.json
rm -f runs/persistent_agent_1_worker_status.json
rm -f runs/persistent_agent_1_policy.pt
rm -f runs/persistent_agent_1_policy.pt.tmp
rm -f runs/persistent_agent_1_policy_bootstrap.zip
rm -f runs/persistent_agent_1_policy_bootstrap.tmp.zip

LATEST="$(
python - <<'PY'
from pathlib import Path
import re
best = None
for p in Path("runs").glob("poke_*_steps.zip"):
    m = re.fullmatch(r"poke_(\d+)_steps\.zip", p.name)
    if m:
        item = (int(m.group(1)), p)
        if best is None or item[0] > best[0]:
            best = item
if best:
    print(best[1])
PY
)"

STAMP="$(date +%Y%m%d_%H%M%S)"
[[ -f pokemon_training.log ]] && \
    cp -a pokemon_training.log "pokemon_training_before_v32_start_${STAMP}.log" || true
: > pokemon_training.log

if [[ -n "$LATEST" ]]; then
    CHECKPOINT="${LATEST%.zip}"
    echo "PPO hervatten vanaf: $LATEST"
    TRAIN_INNER="printf '%s\\n' '$CHECKPOINT' | python -u baseline_fast_v2.py"
else
    echo "Geen checkpoint: PPO start vanaf 0."
    TRAIN_INNER="python -u baseline_fast_v2.py"
fi

tmux new-session -d -s pokemonred \
"bash -lc 'source ~/miniconda3/etc/profile.d/conda.sh; conda activate pokemonredv2; cd ~/PokemonRedExperiments-v2/v2; export POKEMON_TOTAL_AGENTS=$TOTAL_AGENTS; export AGENT1_SPEED_RATIO=$TARGET_RATIO; export AGENT1_LEAD_STEPS=$LEAD_STEPS; $TRAIN_INNER 2>&1 | tee pokemon_training.log; echo; echo TRAINING GESTOPT; exec bash'"

tmux new-session -d -s pokemonlive \
"cd /home/nico/PokemonRedExperiments-v2/v2 && /home/nico/miniconda3/envs/pokemonredv2/bin/python -u live_server.py"

tmux new-session -d -s tensorboard \
"bash -lc 'source ~/miniconda3/etc/profile.d/conda.sh; conda activate pokemonredv2; cd ~/PokemonRedExperiments-v2/v2; tensorboard --logdir runs --host 0.0.0.0 --port 6006'"

echo
echo "Gestart."
echo "Live:        http://192.168.129.83:8080"
echo "TensorBoard: http://192.168.129.83:6006"

STARTV32
chmod +x "$BASE/start_pokemonred_v3_2.sh"

cat > "$BASE/stop_pokemonred_v3_2.sh" <<'STOPV32'
#!/usr/bin/env bash
set -euo pipefail
cd "$HOME/PokemonRedExperiments-v2/v2"

echo "V3.2 netjes stoppen..."
tmux send-keys -t pokemonred C-c 2>/dev/null || true

for _ in $(seq 1 45); do
    if ! pgrep -f '[b]aseline_fast_v2.py' >/dev/null 2>&1; then
        break
    fi
    sleep 1
done

if pgrep -f '[b]aseline_fast_v2.py' >/dev/null 2>&1; then
    echo "WAARSCHUWING: training reageerde niet; beëindigen."
    pkill -f '[b]aseline_fast_v2.py' 2>/dev/null || true
    sleep 2
fi

tmux kill-session -t pokemonred 2>/dev/null || true
tmux kill-session -t pokemonlive 2>/dev/null || true
tmux kill-session -t tensorboard 2>/dev/null || true
pkill -f '[l]ive_server.py' 2>/dev/null || true
pkill -f '[t]ensorboard' 2>/dev/null || true

echo "V3.2 gestopt."

STOPV32
chmod +x "$BASE/stop_pokemonred_v3_2.sh"

"$PYENV" -m py_compile   baseline_fast_v2.py   persistent_explorer_callback.py   live_server.py   red_gym_env_v2.py   tensorboard_callback.py

echo
echo "============================================================"
echo " V3.2 AUTO SPEED BALANCER GEÏNSTALLEERD"
echo "============================================================"
echo
echo "Bot staat UIT."
echo
echo "Start standaard 12 totaal:"
echo "  ./start_pokemonred_v3_2.sh"
echo
echo "Later met 32 GB en 20 totaal:"
echo "  ./start_pokemonred_v3_2.sh 20"
echo
echo "RAM-automatisch:"
echo "  ./start_pokemonred_v3_2.sh auto"
echo
echo "Agent 1 past zijn snelheid automatisch aan het aantal PPO trainers aan."
echo "Backup: $BACKUP"
